// Builds worker/discord-feed.js: one file to paste into the Cloudflare dashboard (no wrangler needed).
// Run: node worker/bundle.js
const fs = require('node:fs');
const path = require('node:path');

const read = (p) => fs.readFileSync(path.join(__dirname, p), 'utf8');
const wrap = (name, src) => `const ${name} = (function () { const module = { exports: {} }; ${'\n'}${src}${'\n'}return module.exports; })();\n`;

function bundle() {
  const main = read('index.mjs')
    .replace("import Calls from '../calls.js';\n", '')
    .replace("import Feed from './feed-core.js';\n", '');
  return '// GENERATED by `node worker/bundle.js` from calls.js, worker/feed-core.js and worker/index.mjs. Do not edit.\n'
    + wrap('Calls', read('../calls.js'))
    + wrap('Feed', read('feed-core.js'))
    + main;
}

if (require.main === module) {
  fs.writeFileSync(path.join(__dirname, 'discord-feed.js'), bundle());
  console.log('wrote worker/discord-feed.js');
}
module.exports = { bundle };
